/**
 * freq_div.v
 *
 * Frequency Divider Module - Hybrid Modular Clock Divider Implementation
 *
 * Inputs:
 *   CLK_in - 100 MHz input clock
 *   RST    - Asynchronous active-high reset
 *
 * Outputs:
 *   CLK_50 - 50 MHz clock output (CLK_in / 2)
 *   CLK_10 - 10 MHz clock output (CLK_in / 10)
 *   CLK_1  -  1 MHz clock output (CLK_in / 100)
 *
 * Implementation:
 *   - CLK_50 toggled every clock cycle in a dedicated always block (divide by 2).
 *   - CLK_10 and CLK_1 generated by counters and toggled in a shared always block:
 *       * CLK_10 toggles every 5 CLK_in cycles (cnt_10 counts 0 to 4).
 *       * CLK_1 toggles every 50 CLK_in cycles (cnt_100 counts 0 to 49).
 *   - Asynchronous active-high reset initializes all outputs and counters.
 *   - Non-blocking assignments ensure proper synchronous behavior.
 */

module freq_div (
    input  wire CLK_in,
    input  wire RST,
    output reg  CLK_50,
    output reg  CLK_10,
    output reg  CLK_1
);

    // Counter for CLK_10: counts 0 to 4 for divide by 10 (toggle every 5 cycles)
    reg [2:0] cnt_10;
    // Counter for CLK_1: counts 0 to 49 for divide by 100 (toggle every 50 cycles)
    reg [5:0] cnt_100;

    // CLK_50 generation: toggle every clock cycle -> frequency division by 2
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            CLK_50 <= 1'b0;
        end else begin
            CLK_50 <= ~CLK_50;
        end
    end

    // CLK_10 and CLK_1 generation: combined slower frequency dividers
    always @(posedge CLK_in or posedge RST) begin
        if (RST) begin
            cnt_10 <= 3'd0;
            CLK_10 <= 1'b0;
            cnt_100 <= 6'd0;
            CLK_1 <= 1'b0;
        end else begin
            // CLK_10 divider (divide by 10): toggle every 5 cycles
            if (cnt_10 == 3'd4) begin
                cnt_10 <= 3'd0;
                CLK_10 <= ~CLK_10;
            end else begin
                cnt_10 <= cnt_10 + 1'b1;
            end

            // CLK_1 divider (divide by 100): toggle every 50 cycles
            if (cnt_100 == 6'd49) begin
                cnt_100 <= 6'd0;
                CLK_1 <= ~CLK_1;
            end else begin
                cnt_100 <= cnt_100 + 1'b1;
            end
        end
    end

endmodule